// Cria aliases automaticos sem underscore no bloco (ex: fisica_optica_bloco4_D1 <-> fisica_optica_bloco_4_D1)
Object.keys(window.OpticaTopicResources).forEach(function(k) {
  var alias = k.replace('_bloco_', '_bloco');
  if (alias !== k && !window.OpticaTopicResources[alias]) {
    window.OpticaTopicResources[alias] = window.OpticaTopicResources[k];
  }
  var aliasAlt = k.replace('_bloco', '_bloco_');
  if (aliasAlt !== k && !window.OpticaTopicResources[aliasAlt]) {
    window.OpticaTopicResources[aliasAlt] = window.OpticaTopicResources[k];
  }
});
